def paths(grid):  # 1 = blocked
    if not grid:
        return 0
    n = len(grid[0])
    if any(len(r) != n for r in grid):
        raise ValueError("rectangular grid")
    if any(x not in (0, 1)
           for r in grid for x in r):
        raise ValueError("binary grid")
    if n == 0:
        return 0

